package com.formation.book.service;
import com.formation.book.exception.StockConflictException; import com.formation.book.model.Book; import com.formation.book.repository.BookRepository; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.util.Optional; import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class BookServiceTest { @Mock BookRepository repository; @InjectMocks BookService service; @Test void decrementStockExhaustedReturnsConflict(){Book b=new Book("Titre","Auteur","isbn",1,0);when(repository.findById(1L)).thenReturn(Optional.of(b));assertThrows(StockConflictException.class,()->service.decrement(1L));verify(repository,never()).saveAndFlush(any());} }
